function getRegionalMultiplier(zipCode) {
  const prefix = zipCode.substring(0, 3);
  const exact = REGIONAL_MULTIPLIERS[prefix];
  if (exact) return exact;
  const state = getStateFromZip(zipCode);
  const stateLevel = state ? STATE_FALLBACK_MULTIPLIERS[state] : void 0;
  if (stateLevel) return { multiplier: stateLevel, market: `${state} (statewide average)` };
  return { multiplier: 1, market: "National Average" };
}

