  tall_ceiling: 1.15,
  // 10-12ft
  vaulted: 1.3,
  // 12ft+, angles
  second_story_exterior: 1.2,
  third_story_exterior: 1.5,
  // Detail level
  simple_flat: 1,
  // flat walls, basic
  textured_wall: 1.05,
  // textured drywall
  detailed_trim: 1.15,
  // intricate profiles
  multi_pane_windows: 1.3,
  // french panes, lots of cutting in
